#include <iostream>
using namespace std;

template <typename T>
struct Tag {
    static const char* name() { return "普通料"; }
};

template <typename T>
struct Tag<T*> {
    static const char* name() { return "指向牌"; }
};

template <>
struct Tag<bool> {
    static const char* name() { return "对错料"; }
};

int main() {
    cout << "{t} 走 " << Tag<{t}>::name() << endl;
    cout << "{t}* 走 " << Tag<{t}*>::name() << endl;
    cout << "bool 走 " << Tag<bool>::name() << endl;
    return 0;
}
